mapper.select:
SELECT
f.*,

FROM mes_fault_record f
LEFT JOIN mes_equipment e ON f.equipment_id = e.equipment_id
WHERE 1=1

    AND f.fault_no LIKE CONCAT('%', #{query.faultNo}, '%')


    AND f.equipment_id = #{query.equipmentId}


    AND e.equipment_code = #{query.equipmentCode}


    AND e.equipment_name LIKE CONCAT('%', #{query.equipmentName}, '%')


    AND f.fault_type = #{query.faultType}


    AND f.fault_level = #{query.faultLevel}


    AND f.fault_status = #{query.faultStatus}


    AND f.occur_time >= #{query.occurTimeStart}


    AND f.occur_time <= #{query.occurTimeEnd}


    AND f.discoverer LIKE CONCAT('%', #{query.discoverer}, '%')


    AND f.handler LIKE CONCAT('%', #{query.handler}, '%')


    AND f.is_recurring = #{query.isRecurring}


    AND f.fault_status = 2
    AND f.treatment_start_time IS NOT NULL
    AND TIMESTAMPDIFF(HOUR, f.treatment_start_time, NOW()) > 24


    AND e.workshop = #{query.workshop}


    AND e.equipment_type = #{query.equipmentType}



    AND (
    f.fault_no LIKE CONCAT('%', #{query.keyword}, '%')
    OR f.phenomenon LIKE CONCAT('%', #{query.keyword}, '%')
    OR f.treatment_measures LIKE CONCAT('%', #{query.keyword}, '%')
    OR f.cause_analysis LIKE CONCAT('%', #{query.keyword}, '%')
    OR e.equipment_code LIKE CONCAT('%', #{query.keyword}, '%')
    OR e.equipment_name LIKE CONCAT('%', #{query.keyword}, '%')
    )



    AND f.fault_status != 4

ORDER BY



            f.occur_time
            f.treatment_start_time
            f.fault_level
            f.fault_status
            e.equipment_code
            e.equipment_name
            f.${query.sortField}

        ${query.sortOrder}


        f.occur_time DESC

SELECT fault_type, COUNT(*) as count, SUM(estimated_loss) as total_loss, AVG(actual_downtime_hours) as avg_downtime FROM mes_fault_record WHERE 1=1
AND occur_time >= #{startTime}
AND occur_time <= #{endTime}
GROUP BY fault_type ORDER BY count DESC

SELECT fault_level, COUNT(*) as count, SUM(estimated_loss) as total_loss, AVG(actual_downtime_hours) as avg_downtime FROM mes_fault_record WHERE 1=1
AND occur_time >= #{startTime}
AND occur_time <= #{endTime}
GROUP BY fault_level ORDER BY fault_level

SELECT fault_status, COUNT(*) as count, SUM(CASE WHEN fault_status = 3 THEN estimated_loss ELSE 0 END) as resolved_loss, SUM(CASE WHEN fault_status = 2 THEN actual_downtime_hours ELSE 0 END) as processing_downtime FROM mes_fault_record WHERE 1=1
AND occur_time >= #{startTime}
AND occur_time <= #{endTime}
GROUP BY fault_status ORDER BY fault_status

SELECT e.equipment_code, e.equipment_name, e.equipment_type, e.workshop, COUNT(f.fault_id) as fault_count, SUM(f.estimated_loss) as total_loss, SUM(f.actual_downtime_hours) as total_downtime, AVG(f.actual_downtime_hours) as avg_downtime FROM mes_equipment e LEFT JOIN mes_fault_record f ON e.equipment_id = f.equipment_id WHERE e.is_active = 1
AND f.occur_time >= #{startTime}
AND f.occur_time <= #{endTime}
GROUP BY e.equipment_id, e.equipment_code, e.equipment_name, e.equipment_type, e.workshop HAVING fault_count > 0 ORDER BY fault_count DESC LIMIT 20

mapper.update:
UPDATE mes_fault_record
SET
fault_status = #{faultStatus},
update_time = #{updateTime}

    , closer = #{operator}
    , close_time = #{updateTime}

WHERE fault_id = #{faultId}

mapper.select:
SELECT e.equipment_id, e.equipment_code, e.equipment_name, COUNT(f.fault_id) as total_faults, SUM(CASE WHEN f.fault_status IN (1,2) THEN 1 ELSE 0 END) as unresolved_faults, SUM(CASE WHEN f.fault_status = 3 THEN 1 ELSE 0 END) as resolved_faults, SUM(f.estimated_loss) as total_loss, SUM(f.actual_downtime_hours) as total_downtime, AVG(f.actual_downtime_hours) as avg_downtime, MAX(f.occur_time) as last_fault_time FROM mes_equipment e LEFT JOIN mes_fault_record f ON e.equipment_id = f.equipment_id WHERE e.is_active = 1
AND e.workshop = #{workshop}
AND e.equipment_type = #{equipmentType}
AND f.occur_time >= #{startTime}
AND f.occur_time <= #{endTime}
GROUP BY e.equipment_id, e.equipment_code, e.equipment_name HAVING total_faults > 0 ORDER BY total_faults DESC

SELECT DATE(occur_time) as date, COUNT(*) as fault_count, SUM(estimated_loss) as total_loss, SUM(actual_downtime_hours) as total_downtime, SUM(CASE WHEN fault_level = 4 THEN 1 ELSE 0 END) as critical_count, SUM(CASE WHEN fault_level = 3 THEN 1 ELSE 0 END) as serious_count FROM mes_fault_record WHERE 1=1
AND occur_time >= #{startTime}
AND occur_time <= #{endTime}
AND equipment_id = #{equipmentId}
AND equipment_id IN (SELECT equipment_id FROM mes_equipment WHERE workshop = #{workshop})
GROUP BY DATE(occur_time) ORDER BY date
